cd "D:/Projects/veripaka/.temp/s2-start/r2/pixel-consumer" && node -e "
const fs=require('fs');
for(const f of ['reference.png','candidate.png']){
  const b=fs.readFileSync(f);
  console.log('==',f,'bytes',b.length);
  console.log(' sig ok', b.slice(0,8).toString('hex')==='89504e470d0a1a0a');
  let o=8; const chunks=[];
  while(o<b.length){
    const len=b.readUInt32BE(o); const type=b.slice(o+4,o+8).toString('latin1');
    chunks.push(type+':'+len);
    if(type==='IHDR'){
      console.log('  IHDR w',b.readUInt32BE(o+8),'h',b.readUInt32BE(o+12),'bitDepth',b[o+16],'colorType',b[o+17],'compression',b[o+18],'filter',b[o+19],'interlace',b[o+20]);
    }
    if(type==='IEND')break;
    o+=12+len;
  }
  console.log('  chunks',chunks.join(' '));
}
"
